 static void swipe(MainActivity a,boolean right,boolean vertical){float x=a.scroll.getWidth()*(right?.2f:.8f),y=400,finishX=vertical?x+5:a.scroll.getWidth()*(right?.8f:.2f),finishY=vertical?y+450:y;long time=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,0,x,y,0);a.scroll.dispatchTouchEvent(down);down.recycle();for(int i=1;i<=4;i++){android.view.MotionEvent move=android.view.MotionEvent.obtain(time,time+i*50,2,x+(finishX-x)*i/4,y+(finishY-y)*i/4,0);a.scroll.dispatchTouchEvent(move);move.recycle();}android.view.MotionEvent up=android.view.MotionEvent.obtain(time,time+250,1,finishX,finishY,0);a.scroll.dispatchTouchEvent(up);up.recycle();}
 static void shot(Instrumentation test,Context c,String name)throws Exception{Thread.sleep(800);Bitmap image=test.getUiAutomation().takeScreenshot();if(image==null)throw new Exception("Screenshot failed: "+name);File dir=new File(c.getExternalFilesDir(null),"qa");dir.mkdirs();try(FileOutputStream stream=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}image.recycle();}
